import{_ as t,o as r,c as a,a3 as o}from"./chunks/framework.I6s8z2kk.js";const p=JSON.parse('{"title":"Architecture overview","description":"","frontmatter":{},"headers":[],"relativePath":"dev/architecture/overview.md","filePath":"dev/architecture/overview.md"}'),s={name:"dev/architecture/overview.md"};function i(d,e,n,c,l,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="architecture-overview" tabindex="-1">Architecture overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture overview&quot;">​</a></h1><p>Khyyal is a <strong>modular monolith</strong>: one Laravel application whose code is split into modules under <code>modules/</code>. Modules talk to each other through models, events and a few contracts, never through HTTP.</p><h2 id="actors-and-surfaces" tabindex="-1">Actors and surfaces <a class="header-anchor" href="#actors-and-surfaces" aria-label="Permalink to &quot;Actors and surfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Actor</th><th>Guard</th><th>Prefix</th><th>Used by</th></tr></thead><tbody><tr><td>Client</td><td><code>client</code></td><td><code>api/v1/clients/*</code></td><td>The client app</td></tr><tr><td>Center user</td><td><code>center_user</code></td><td><code>api/v1/centers/*</code></td><td>The center dashboard and center app</td></tr><tr><td>System user</td><td><code>system_user</code></td><td><code>api/v1/admin/*</code></td><td>The admin panel</td></tr></tbody></table><p>See <a href="./api-surfaces">API surfaces and guards</a>.</p><h2 id="how-a-request-flows" tabindex="-1">How a request flows <a class="header-anchor" href="#how-a-request-flows" aria-label="Permalink to &quot;How a request flows&quot;">​</a></h2><ol><li>A route in a module (<code>modules/&lt;Module&gt;/routes/*.php</code>), mounted under <code>api/v1</code> by the module&#39;s service provider.</li><li>Middleware: guard, <code>center.scope</code> for center routes, locale middleware for client routes.</li><li>A controller that stays thin: a Form Request validates the shape, a policy authorizes, a service does the work.</li><li>A service or action that holds the business rules, usually inside a database transaction.</li><li>An API Resource shapes the response.</li><li>Domain events fire <strong>after commit</strong>; listeners that touch money or send notifications are queued.</li></ol><h2 id="principles" tabindex="-1">Principles <a class="header-anchor" href="#principles" aria-label="Permalink to &quot;Principles&quot;">​</a></h2><ul><li><strong>Money is integer halalas</strong>, percentages are basis points (10000 = 100%). Never floats.</li><li><strong>State changes go through one service</strong> (reservation, purchase and payment status). Never write a status column directly.</li><li><strong>Cross-module access goes through contracts</strong> where the dependency would otherwise be circular. Example: <code>Promotions\\Contracts\\ServicePriceDisplay</code> is used by Homepage, Centers and Services to show discounted prices.</li><li><strong>Everything is audited</strong> where it matters (Activitylog), and analytics keep no personal data.</li><li><strong>Octane</strong>: the app boots once and serves many requests, so no request state in singletons. See <a href="./octane">Octane</a>.</li></ul>',9)])])}const v=t(s,[["render",i]]);export{p as __pageData,v as default};
